   153→## 3. 解决方案
   154→
   155→### 3.1 迁移到 Addressables
   156→
   157→**问题**：Resources.Load 同步加载阻塞主线程
   158→
   159→**方案**：使用 Addressables 异步加载
   160→
   161→#### 步骤1：资源迁移
   162→
   163→```csharp
   164→/// <summary>
   165→/// 资源加载服务 - Addressables封装
   166→/// </summary>
   167→public class AssetLoader : MonoBehaviour
   168→{
   169→    private Dictionary<string, AsyncOperationHandle> loadedHandles = new Dictionary<string, AsyncOperationHandle>();
   170→
   171→    /// <summary>
   172→    /// 异步加载单个资源
   173→    /// </summary>
   174→    public async Task<T> LoadAssetAsync<T>(string address) where T : Object
   175→    {
   176→        // 检查缓存
   177→        if (loadedHandles.TryGetValue(address, out var existingHandle))
   178→        {
   179→            if (existingHandle.IsDone)
   180→            {
   181→                return existingHandle.Result as T;
   182→            }
   183→            await existingHandle.Task;
   184→            return existingHandle.Result as T;
   185→        }
   186→
   187→        // 异步加载
   188→        var handle = Addressables.LoadAssetAsync<T>(address);
   189→        loadedHandles[address] = handle;
   190→
   191→        await handle.Task;
   192→
   193→        if (handle.Status == AsyncOperationStatus.Succeeded)
   194→        {
   195→            return handle.Result;
   196→        }
   197→
   198→        Debug.LogError($"Failed to load asset: {address}");
   199→        return null;
   200→    }
   201→
   202→    /// <summary>
   203→    /// 批量异步加载
   204→    /// </summary>
   205→    public async Task<List<T>> LoadAssetsAsync<T>(IList<string> addresses) where T : Object
   206→    {
   207→        var results = new List<T>();
   208→        var tasks = new List<Task<T>>();
   209→
   210→        foreach (var address in addresses)
   211→        {
   212→            tasks.Add(LoadAssetAsync<T>(address));
   213→        }
   214→
   215→        var loadedAssets = await Task.WhenAll(tasks);
   216→        results.AddRange(loadedAssets.Where(a => a != null));
   217→
   218→        return results;
   219→    }
   220→
   221→    /// <summary>
   222→    /// 释放资源
   223→    /// </summary>
   224→    public void ReleaseAsset(string address)
   225→    {
   226→        if (loadedHandles.TryGetValue(address, out var handle))
   227→        {
   228→            Addressables.Release(handle);
   229→            loadedHandles.Remove(address);
   230→        }
   231→    }
   232→
   233→    /// <summary>
   234→    /// 释放所有资源
   235→    /// </summary>
   236→    public void ReleaseAll()
   237→    {
   238→        foreach (var handle in loadedHandles.Values)
   239→        {
   240→            Addressables.Release(handle);
   241→        }
   242→        loadedHandles.Clear();
   243→    }
   244→}
   245→```
   246→
   247→#### 步骤2：重构UI资源加载
   248→
   249→```csharp
   250→/// <summary>
   251→/// UI管理器 - 异步加载版本
   252→/// </summary>
   253→public class UIManager : MonoBehaviour
   254→{
   255→    [SerializeField] private AssetLoader assetLoader;
   256→
   257→    private Dictionary<string, GameObject> cachedPanels = new Dictionary<string, GameObject>();
   258→
   259→    /// <summary>
   260→    /// 异步打开面板
   261→    /// </summary>
   262→    public async Task<T> OpenPanelAsync<T>(string panelAddress) where T : Component
   263→    {
   264→        // 检查缓存
   265→        if (cachedPanels.TryGetValue(panelAddress, out var cachedPanel))
   266→        {
   267→            cachedPanel.SetActive(true);
   268→            return cachedPanel.GetComponent<T>();
   269→        }
   270→
   271→        // 异步加载
   272→        var prefab = await assetLoader.LoadAssetAsync<GameObject>(panelAddress);
   273→        if (prefab == null) return null;
   274→
   275→        // 实例化
   276→        var panel = Instantiate(prefab, transform);
   277→        cachedPanels[panelAddress] = panel;
   278→
   279→        return panel.GetComponent<T>();
   280→    }
   281→
   282→    /// <summary>
   283→    /// 关闭面板（回收到缓存）
   284→    /// </summary>
   285→    public void ClosePanel(string panelAddress)
   286→    {
   287→        if (cachedPanels.TryGetValue(panelAddress, out var panel))
   288→        {
   289→            panel.SetActive(false);
   290→        }
   291→    }
   292→}
   293→```
   294→
   295→### 3.2 异步场景加载
   296→
   297→**问题**：SceneManager.LoadScene 同步阻塞
   298→
   299→**方案**：使用 LoadSceneAsync + 进度显示
   300→
   301→```csharp
   302→/// <summary>
   303→/// 场景管理器 - 异步加载版本
   304→/// </summary>
   305→public class SceneLoader : MonoBehaviour
   306→{
   307→    [Header("Loading UI")]
   308→    [SerializeField] private GameObject loadingScreen;
   309→    [SerializeField] private Slider progressBar;
   310→    [SerializeField] private Text progressText;
   311→
   312→    private AsyncOperation currentOperation;
   313→
   314→    /// <summary>
   315→    /// 异步加载场景（带进度显示）
   316→    /// </summary>
   317→    public async Task LoadSceneAsync(string sceneName)
   318→    {
   319→        // 显示加载界面
   320→        loadingScreen.SetActive(true);
   321→        UpdateProgress(0f);
   322→
   323→        // 开始异步加载
   324→        currentOperation = SceneManager.LoadSceneAsync(sceneName);
   325→        currentOperation.allowSceneActivation = false;
   326→
   327→        // 更新进度
   328→        while (!currentOperation.isDone)
   329→        {
   330→            // AsyncOperation.progress 在 allowSceneActivation=false 时最大到0.9
   331→            float progress = Mathf.Clamp01(currentOperation.progress / 0.9f);
   332→            UpdateProgress(progress);
   333→
   334→            // 进度达到90%时，准备激活场景
   335→            if (currentOperation.progress >= 0.9f)
   336→            {
   337→                UpdateProgress(1f);
   338→                await Task.Delay(100); // 短暂延迟让用户看到100%
   339→                currentOperation.allowSceneActivation = true;
   340→            }
   341→
   342→            await Task.Yield();
   343→        }
   344→
   345→        // 隐藏加载界面
   346→        loadingScreen.SetActive(false);
   347→    }
   348→
   349→    /// <summary>
   350→    /// 带预加载的场景切换
   351→    /// </summary>
   352→    public async Task LoadSceneWithPreload(string sceneName, List<string> preloadAssets)
   353→    {
   354→        loadingScreen.SetActive(true);
   355→        UpdateProgress(0f);
   356→
   357→        // 阶段1: 加载场景 (0% - 50%)
   358→        var sceneTask = LoadSceneInternal(sceneName);
   359→        var progressTask = MonitorSceneProgress();
   360→
   361→        await sceneTask;
   362→
   363→        // 阶段2: 预加载资源 (50% - 100%)
   364→        UpdateProgress(0.5f);
   365→        await PreloadAssets(preloadAssets, (p) => UpdateProgress(0.5f + p * 0.5f));
   366→
   367→        UpdateProgress(1f);
   368→        await Task.Delay(100);
   369→
   370→        loadingScreen.SetActive(false);
   371→    }
   372→
   373→    private void UpdateProgress(float progress)
   374→    {
   375→        if (progressBar != null)
   376→        {
   377→            progressBar.value = progress;
   378→        }
   379→        if (progressText != null)
   380→        {
   381→            progressText.text = $"加载中... {(int)(progress * 100)}%";
   382→        }
   383→    }
   384→}
   385→```
   386→
   387→### 3.3 分帧初始化
   388→
   389→**问题**：所有Manager在Awake/Start同步初始化导致卡顿
   390→
   391→**方案**：使用协程分帧初始化
   392→
   393→```csharp
   394→/// <summary>
   395→/// 游戏启动器 - 分帧初始化
   396→/// </summary>
   397→public class GameLauncher : MonoBehaviour
   398→{
   399→    [Header("Initialization Order")]
   400→    [SerializeField] private List<MonoBehaviour> initOrder;
   401→
   402→    [Header("Loading UI")]
   403→    [SerializeField] private Slider initProgress;
   404→    [SerializeField] private Text initStatus;
   405→
   406→    private float initStartTime;
   407→
   408→    private async void Start()
   409→    {
   410→        initStartTime = Time.realtimeSinceStartup;
   411→
   412→        // 阶段1: 核心系统初始化
   413→        await InitializePhase("核心系统", new List<Func<Task>>
   414→        {
   415→            () => InitializeManager<AudioManager>(),
   416→            () => InitializeManager<EventManager>(),
   417→            () => InitializeManager<SaveManager>(),
   418→        });
   419→
   420→        // 阶段2: UI初始化
   421→        await InitializePhase("UI系统", new List<Func<Task>>
   422→        {
   423→            () => InitializeManager<UIManager>(),
   424→            () => PreloadUIAssets(),
   425→        });
   426→
   427→        // 阶段3: 游戏系统初始化
   428→        await InitializePhase("游戏系统", new List<Func<Task>>
   429→        {
   430→            () => InitializeManager<GameManager>(),
   431→            () => InitializeManager<CharacterManager>(),
   432→            () => LoadLevelConfig(),
   433→        });
   434→
   435→        // 阶段4: 可延后初始化
   436→        StartCoroutine(DelayedInit());
   437→    }
   438→
   439→    private async Task InitializePhase(string phaseName, List<Func<Task>> tasks)
   440→    {
   441→        UpdateStatus($"正在初始化{phaseName}...");
   442→
   443→        for (int i = 0; i < tasks.Count; i++)
   444→        {
   445→            await tasks[i]();
   446→            UpdateProgress((float)(i + 1) / tasks.Count);
   447→
   448→            // 每个任务后等待一帧，避免卡顿
   449→            await Task.Yield();
   450→        }
   451→    }
   452→
   453→    private IEnumerator DelayedInit()
   454→    {
   455→        // 等待3秒后初始化非关键系统
   456→        yield return new WaitForSeconds(3f);
   457→
   458→        // 后台初始化分析SDK
   459→        Task.Run(() => AnalyticsService.Initialize());
   460→
   461→        // 后台初始化广告SDK
   462→        Task.Run(() => AdService.Initialize());
   463→    }
   464→
   465→    private void UpdateStatus(string status)
   466→    {
   467→        if (initStatus != null)
   468→        {
   469→            initStatus.text = status;
   470→        }
   471→    }
   472→
   473→    private void UpdateProgress(float progress)
   474→    {
   475→        if (initProgress != null)
   476→        {
   477→            initProgress.value = progress;
   478→        }
   479→    }
   480→
   481→    private async Task InitializeManager<T>() where T : MonoBehaviour
   482→    {
   483→        var manager = FindObjectOfType<T>();
   484→        if (manager is IAsyncInitializable asyncInit)
   485→        {
   486→            await asyncInit.InitializeAsync();
   487→        }
   488→    }
   489→}
   490→
   491→/// <summary>
   492→/// 异步初始化接口
   493→/// </summary>
   494→public interface IAsyncInitializable
   495→{
   496→    Task InitializeAsync();
   497→}
   498→```
   499→
   500→### 3.4 配置预加载
   501→
   502→**问题**：JSON配置在主线程解析阻塞
   503→
   504→**方案**：后台线程预加载 + 缓存
   505→
   506→```csharp
   507→/// <summary>
   508→/// 配置管理器 - 异步加载版本
   509→/// </summary>
   510→public class ConfigManager : MonoBehaviour, IAsyncInitializable
   511→{
   512→    private Dictionary<string, object> configCache = new Dictionary<string, object>();
   513→
   514→    public async Task InitializeAsync()
   515→    {
   516→        // 在后台线程加载所有配置
   517→        var configFiles = new Dictionary<string, Type>
   518→        {
   519→            { "Config/levels", typeof(LevelConfigData) },
   520→            { "Config/characters", typeof(CharacterConfigData) },
   521→            { "Config/items", typeof(ItemConfigData) },
   522→            { "Config/iap", typeof(IAPConfigData) },
   523→        };
   524→
   525→        // 并行加载
   526→        var tasks = configFiles.Select(kvp => LoadConfigAsync(kvp.Key, kvp.Value));
   527→        await Task.WhenAll(tasks);
   528→    }
   529→
   530→    private async Task LoadConfigAsync(string address, Type configType)
   531→    {
   532→        var jsonAsset = await Addressables.LoadAssetAsync<TextAsset>(address).Task;
   533→
   534→        if (jsonAsset != null)
   535→        {
   536→            // 在后台线程解析JSON
   537→            var config = await Task.Run(() =>
   538→            {
   539→                return JsonUtility.FromJson(jsonAsset.text, configType);
   540→            });
   541→
   542→            configCache[address] = config;
   543→        }
   544→    }
   545→
   546→    /// <summary>
   547→    /// 获取配置（同步，必须已预加载）
   548→    /// </summary>
   549→    public T GetConfig<T>(string address) where T : class
   550→    {
   551→        if (configCache.TryGetValue(address, out var config))
   552→        {
   553→            return config as T;
   554→        }
   555→        Debug.LogError($"Config not loaded: {address}");
   556→        return null;
   557→    }
   558→}
   559→```
