    15→# 【最佳实践】Addressables性能优化
    16→
    17→> Addressables 资源管理系统的性能优化实战 `#性能优化` `#加载优化` `#Addressables` `#最佳实践`
    18→
    19→## 文档定位
    20→
    21→Unity Addressables资源管理系统的性能优化指南，涵盖异步加载优化（避免同步加载阻塞）、内存管理（正确Release资源、引用计数）、AssetBundle优化（分组策略、压缩格式选择、缓存策略），以及加载性能监控和常见性能陷阱排查。
    22→
    23→---
    24→
    25→## 1. Addressables vs Resources
    26→
    27→### 1.1 为什么选择 Addressables
    28→
    29→```
    30→┌─────────────────────────────────────────────────────────────┐
    31→│              Resources.Load vs Addressables                  │
    32→├─────────────────────────────────────────────────────────────┤
    33→│                                                             │
    34→│  Resources.Load 问题：                                      │
    35→│  ├── 同步阻塞主线程                                        │
    36→│  ├── 无法精确控制内存                                      │
    37→│  ├── 增加初始包体大小                                      │
    38→│  └── 无法热更新                                            │
    39→│                                                             │
    40→│  Addressables 优势：                                        │
    41→│  ├── ✅ 异步加载，不阻塞主线程                             │
    42→│  ├── ✅ 引用计数内存管理                                   │
    43→│  ├── ✅ 本地/远程资源统一接口                              │
    44→│  ├── ✅ 支持热更新和 DLC                                   │
    45→│  └── ✅ 自动依赖管理                                       │
    46→│                                                             │
    47→└─────────────────────────────────────────────────────────────┘
    48→```
    49→
    50→### 1.2 性能对比
    51→
    52→| 方案 | 内存占用 | 加载时间 | 灵活性 | 推荐场景 |
    53→|------|---------|---------|--------|---------|
    54→| Resources.Load | 低 | 快（同步阻塞） | 低 | 小型项目、原型 |
    55→| AssetBundle | 中 | 中（异步） | 高 | 大型项目、热更 |
    56→| Addressables | 中 | 中（异步） | 高 | 所有项目（推荐） |
    57→
    58→---
    59→
    60→## 2. 异步加载优化
    61→
    62→### 2.1 基础异步加载
    63→
    64→```csharp
    65→using UnityEngine;
    66→using UnityEngine.AddressableAssets;
    67→using UnityEngine.ResourceManagement.AsyncOperations;
    68→using System.Collections.Generic;
    69→using System.Threading.Tasks;
    70→
    71→/// <summary>
    72→/// Addressables 异步加载管理器
    73→/// </summary>
    74→public class AddressablesLoader : MonoBehaviour
    75→{
    76→    private Dictionary<string, AsyncOperationHandle> loadedHandles = new Dictionary<string, AsyncOperationHandle>();
    77→    private Dictionary<string, int> referenceCounts = new Dictionary<string, int>();
    78→
    79→    /// <summary>
    80→    /// 异步加载单个资源
    81→    /// </summary>
    82→    public async Task<T> LoadAssetAsync<T>(string address) where T : Object
    83→    {
    84→        // 检查缓存
    85→        if (loadedHandles.TryGetValue(address, out var existingHandle))
    86→        {
    87→            if (existingHandle.IsDone)
    88→            {
    89→                referenceCounts[address]++;
    90→                return existingHandle.Result as T;
    91→            }
    92→            await existingHandle.Task;
    93→            referenceCounts[address]++;
    94→            return existingHandle.Result as T;
    95→        }
    96→
    97→        // 异步加载
    98→        var handle = Addressables.LoadAssetAsync<T>(address);
    99→        loadedHandles[address] = handle;
   100→        referenceCounts[address] = 1;
   101→
   102→        await handle.Task;
   103→
   104→        if (handle.Status == AsyncOperationStatus.Succeeded)
   105→        {
   106→            return handle.Result;
   107→        }
   108→
   109→        Debug.LogError($"Failed to load asset: {address}");
   110→        loadedHandles.Remove(address);
   111→        referenceCounts.Remove(address);
   112→        return null;
   113→    }
   114→
   115→    /// <summary>
   116→    /// 批量异步加载
   117→    /// </summary>
   118→    public async Task<List<T>> LoadAssetsAsync<T>(IList<string> addresses) where T : Object
   119→    {
   120→        var results = new List<T>();
   121→        var tasks = new List<Task<T>>();
   122→
   123→        foreach (var address in addresses)
   124→        {
   125→            tasks.Add(LoadAssetAsync<T>(address));
   126→        }
   127→
   128→        var loadedAssets = await Task.WhenAll(tasks);
   129→        results.AddRange(loadedAssets.Where(a => a != null));
   130→
   131→        return results;
   132→    }
   133→
   134→    /// <summary>
   135→    /// 释放资源
   136→    /// </summary>
   137→    public void ReleaseAsset(string address)
   138→    {
   139→        if (!referenceCounts.TryGetValue(address, out var count))
   140→            return;
   141→
   142→        count--;
   143→        referenceCounts[address] = count;
   144→
   145→        if (count <= 0)
   146→        {
   147→            if (loadedHandles.TryGetValue(address, out var handle))
   148→            {
   149→                Addressables.Release(handle);
   150→                loadedHandles.Remove(address);
   151→            }
   152→            referenceCounts.Remove(address);
   153→        }
   154→    }
   155→
   156→    /// <summary>
   157→    /// 释放所有资源
   158→    /// </summary>
   159→    public void ReleaseAll()
   160→    {
   161→        foreach (var handle in loadedHandles.Values)
   162→        {
   163→            Addressables.Release(handle);
   164→        }
   165→        loadedHandles.Clear();
   166→        referenceCounts.Clear();
   167→    }
   168→
   169→    private void OnDestroy()
   170→    {
   171→        ReleaseAll();
   172→    }
   173→}
