   176→### 2.2 带进度的异步加载
   177→
   178→```csharp
   179→/// <summary>
   180→/// 带进度回调的异步加载
   181→/// </summary>
   182→public class ProgressLoader : MonoBehaviour
   183→{
   184→    /// <summary>
   185→    /// 加载资源并报告进度
   186→    /// </summary>
   187→    public async Task<T> LoadWithProgress<T>(
   188→        string address,
   189→        System.Action<float> onProgress = null) where T : Object
   190→    {
   191→        var handle = Addressables.LoadAssetAsync<T>(address);
   192→
   193→        // 等待加载完成，同时报告进度
   194→        while (!handle.IsDone)
   195→        {
   196→            onProgress?.Invoke(handle.PercentComplete);
   197→            await Task.Delay(16); // ~60fps
   198→        }
   199→
   200→        onProgress?.Invoke(1f);
   201→
   202→        if (handle.Status == AsyncOperationStatus.Succeeded)
   203→        {
   204→            return handle.Result;
   205→        }
   206→
   207→        return null;
   208→    }
   209→
   210→    /// <summary>
   211→    /// 批量加载并报告总进度
   212→    /// </summary>
   213→    public async Task<List<T>> LoadMultipleWithProgress<T>(
   214→        IList<string> addresses,
   215→        System.Action<float> onProgress = null) where T : Object
   216→    {
   217→        var results = new List<T>();
   218→        int totalCount = addresses.Count;
   219→        int loadedCount = 0;
   220→
   221→        foreach (var address in addresses)
   222→        {
   223→            var asset = await LoadWithProgress<T>(address, progress =>
   224→            {
   225→                // 计算总进度
   226→                float overallProgress = (loadedCount + progress) / totalCount;
   227→                onProgress?.Invoke(overallProgress);
   228→            });
   229→
   230→            if (asset != null)
   231→            {
   232→                results.Add(asset);
   233→            }
   234→            loadedCount++;
   235→        }
   236→
   237→        return results;
   238→    }
   239→}
