   263→    private bool isPreloading;
   264→
   265→    /// <summary>
   266→    /// 预加载指定组
   267→    /// </summary>
   268→    public async Task<bool> PreloadGroup(string groupName, System.Action<float> onProgress = null)
   269→    {
   270→        var group = System.Array.Find(preloadGroups, g => g.groupName == groupName);
   271→        if (group == null)
   272→        {
   273→            Debug.LogError($"Preload group not found: {groupName}");
   274→            return false;
   275→        }
   276→
   277→        return await PreloadAssets(group.assetAddresses, onProgress);
   278→    }
   279→
   280→    /// <summary>
   281→    /// 预加载资源列表
   282→    /// </summary>
   283→    public async Task<bool> PreloadAssets(string[] addresses, System.Action<float> onProgress = null)
   284→    {
   285→        if (isPreloading)
   286→        {
   287→            Debug.LogWarning("Already preloading");
   288→            return false;
   289→        }
   290→
   291→        isPreloading = true;
   292→        int loadedCount = 0;
   293→        int totalCount = addresses.Length;
   294→
   295→        foreach (var address in addresses)
   296→        {
   297→            if (preloadedAssets.ContainsKey(address))
   298→            {
   299→                loadedCount++;
   300→                continue;
   301→            }
   302→
   303→            var handle = Addressables.LoadAssetAsync<Object>(address);
   304→            await handle.Task;
   305→
   306→            if (handle.Status == AsyncOperationStatus.Succeeded)
   307→            {
   308→                preloadedAssets[address] = handle.Result;
   309→            }
   310→            else
   311→            {
   312→                Debug.LogWarning($"Failed to preload: {address}");
   313→            }
   314→
   315→            loadedCount++;
   316→            onProgress?.Invoke((float)loadedCount / totalCount);
   317→        }
   318→
   319→        isPreloading = false;
   320→        return true;
   321→    }
   322→
   323→    /// <summary>
   324→    /// 获取预加载的资源
   325→    /// </summary>
   326→    public T GetPreloadedAsset<T>(string address) where T : Object
   327→    {
   328→        if (preloadedAssets.TryGetValue(address, out var asset))
   329→        {
   330→            return asset as T;
   331→        }
   332→        return null;
   333→    }
   334→
   335→    /// <summary>
   336→    /// 后台预加载（不阻塞游戏）
   337→    /// </summary>
   338→    public void PreloadInBackground(string groupName)
   339→    {
   340→        StartCoroutine(PreloadCoroutine(groupName));
   341→    }
   342→
   343→    private System.Collections.IEnumerator PreloadCoroutine(string groupName)
   344→    {
   345→        var group = System.Array.Find(preloadGroups, g => g.groupName == groupName);
   346→        if (group == null) yield break;
   347→
   348→        foreach (var address in group.assetAddresses)
   349→        {
   350→            if (preloadedAssets.ContainsKey(address))
   351→                continue;
   352→
   353→            var handle = Addressables.LoadAssetAsync<Object>(address);
   354→            yield return handle;
   355→
   356→            if (handle.Status == AsyncOperationStatus.Succeeded)
   357→            {
   358→                preloadedAssets[address] = handle.Result;
   359→            }
   360→
   361→            // 每加载一个资源，等待一帧
   362→            yield return null;
   363→        }
   364→    }
   365→}
