   370→## 3. 内存管理优化
   371→
   372→### 3.1 引用计数管理
   373→
   374→```csharp
   375→/// <summary>
   376→/// 引用计数资源管理器
   377→/// </summary>
   378→public class ReferenceCountedLoader : MonoBehaviour
   379→{
   380→    private class AssetInfo
   381→    {
   382→        public AsyncOperationHandle Handle;
   383→        public int ReferenceCount;
   384→        public float LastAccessTime;
   385→    }
   386→
   387→    private Dictionary<string, AssetInfo> loadedAssets = new Dictionary<string, AssetInfo>();
   388→
   389→    [Header("Memory Management")]
   390→    [SerializeField] private float unloadUnusedAfterSeconds = 60f;
   391→    [SerializeField] private int maxCachedAssets = 100;
   392→
   393→    /// <summary>
   394→    /// 获取资源（增加引用计数）
   395→    /// </summary>
   396→    public async Task<T> GetAsset<T>(string address) where T : Object
   397→    {
   398→        if (loadedAssets.TryGetValue(address, out var info))
   399→        {
   400→            info.ReferenceCount++;
   401→            info.LastAccessTime = Time.time;
   402→            return info.Handle.Result as T;
   403→        }
   404→
   405→        var handle = Addressables.LoadAssetAsync<T>(address);
   406→        await handle.Task;
   407→
   408→        if (handle.Status == AsyncOperationStatus.Failed)
   409→        {
   410→            Debug.LogError($"Failed to load: {address}");
   411→            return null;
   412→        }
   413→
   414→        loadedAssets[address] = new AssetInfo
   415→        {
   416→            Handle = handle,
   417→            ReferenceCount = 1,
   418→            LastAccessTime = Time.time
   419→        };
   420→
   421→        return handle.Result;
   422→    }
   423→
   424→    /// <summary>
   425→    /// 释放资源引用
   426→    /// </summary>
   427→    public void ReleaseAsset(string address)
   428→    {
   429→        if (!loadedAssets.TryGetValue(address, out var info))
   430→            return;
   431→
   432→        info.ReferenceCount--;
   433→
   434→        if (info.ReferenceCount <= 0)
   435→        {
   436→            // 不立即卸载，等待自动清理
   437→            info.LastAccessTime = Time.time;
   438→        }
   439→    }
   440→
   441→    /// <summary>
   442→    /// 定期清理未使用的资源
   443→    /// </summary>
   444→    private void Update()
   445→    {
   446→        if (Time.frameCount % 300 != 0) // 每5秒检查一次
   447→            return;
   448→
   449→        var keysToRemove = new List<string>();
   450→        float currentTime = Time.time;
   451→
   452→        foreach (var kvp in loadedAssets)
   453→        {
   454→            if (kvp.Value.ReferenceCount <= 0 &&
   455→                currentTime - kvp.Value.LastAccessTime > unloadUnusedAfterSeconds)
   456→            {
   457→                keysToRemove.Add(kvp.Key);
   458→            }
   459→        }
   460→
   461→        foreach (var key in keysToRemove)
   462→        {
   463→            Addressables.Release(loadedAssets[key].Handle);
   464→            loadedAssets.Remove(key);
   465→            Debug.Log($"Unloaded unused asset: {key}");
   466→        }
   467→    }
   468→
   469→    /// <summary>
   470→    /// 强制清理超出限制的缓存
   471→    /// </summary>
   472→    public void EnforceCacheLimit()
   473→    {
   474→        if (loadedAssets.Count <= maxCachedAssets)
   475→            return;
   476→
   477→        // 按 LastAccessTime 排序，移除最旧的
   478→        var sortedAssets = loadedAssets
   479→            .OrderBy(x => x.Value.LastAccessTime)
   480→            .ToList();
   481→
   482→        int toRemove = loadedAssets.Count - maxCachedAssets;
   483→        for (int i = 0; i < toRemove; i++)
   484→        {
   485→            var kvp = sortedAssets[i];
   486→            if (kvp.Value.ReferenceCount <= 0)
   487→            {
   488→                Addressables.Release(kvp.Value.Handle);
   489→                loadedAssets.Remove(kvp.Key);
   490→            }
   491→        }
   492→    }
   493→
   494→    /// <summary>
   495→    /// 获取内存使用统计
   496→    /// </summary>
   497→    public string GetMemoryStats()
   498→    {
   499→        int totalAssets = loadedAssets.Count;
   500→        int activeAssets = loadedAssets.Count(x => x.Value.ReferenceCount > 0);
   501→
   502→        return $"Total: {totalAssets}, Active: {activeAssets}";
   503→    }
   504→}
   505→```
