   699→### 4.3 下载优化
   700→
   701→```csharp
   702→/// <summary>
   703→/// 远程资源下载管理器
   704→/// </summary>
   705→public class RemoteAssetDownloader : MonoBehaviour
   706→{
   707→    [Header("Download Settings")]
   708→    [SerializeField] private int maxConcurrentDownloads = 4;
   709→    [SerializeField] private float timeoutSeconds = 30f;
   710→
   711→    /// <summary>
   712→    /// 下载指定 Label 的所有资源
   713→    /// </summary>
   714→    public async Task<DownloadResult> DownloadLabelAsync(
   715→        string label,
   716→        System.Action<float> onProgress = null)
   717→    {
   718→        var result = new DownloadResult();
   719→
   720→        // 获取下载大小
   721→        var sizeHandle = Addressables.GetDownloadSizeAsync(label);
   722→        await sizeHandle.Task;
   723→
   724→        result.TotalSize = sizeHandle.Result;
   725→        result.TotalSizeMB = result.TotalSize / 1024f / 1024f;
   726→
   727→        if (result.TotalSize <= 0)
   728→        {
   729→            result.AlreadyDownloaded = true;
   730→            return result;
   731→        }
   732→
   733→        // 开始下载
   734→        var downloadHandle = Addressables.DownloadDependenciesAsync(label);
   735→
   736→        while (!downloadHandle.IsDone)
   737→        {
   738→            result.DownloadedBytes = downloadHandle.GetDownloadStatus().DownloadedBytes;
   739→            result.Progress = downloadHandle.GetDownloadStatus().Percent;
   740→
   741→            onProgress?.Invoke(result.Progress);
   742→
   743→            await Task.Delay(100);
   744→        }
   745→
   746→        if (downloadHandle.Status == AsyncOperationStatus.Succeeded)
   747→        {
   748→            result.Success = true;
   749→        }
   750→        else
   751→        {
   752→            result.Success = false;
   753→            result.ErrorMessage = "Download failed";
   754→        }
   755→
   756→        Addressables.Release(downloadHandle);
   757→        return result;
   758→    }
   759→
   760→    public class DownloadResult
   761→    {
   762→        public bool Success;
   763→        public bool AlreadyDownloaded;
   764→        public long TotalSize;
   765→        public float TotalSizeMB;
   766→        public long DownloadedBytes;
   767→        public float Progress;
   768→        public string ErrorMessage;
   769→    }
   770→
   771→    /// <summary>
   772→    /// 清理下载缓存
   773→    /// </summary>
   774→    public async Task ClearCacheAsync()
   775→    {
   776→        await Addressables.ClearDependencyCacheAsync("");
   777→        Debug.Log("Cache cleared");
   778→    }
   779→}
