   797→        public float StartTime;
   798→        public float Duration;
   799→        public bool Success;
   800→    }
   801→
   802→    private List<LoadRecord> loadRecords = new List<LoadRecord>();
   803→    private int maxRecords = 100;
   804→
   805→    /// <summary>
   806→    /// 带性能追踪的加载
   807→    /// </summary>
   808→    public async Task<T> LoadWithProfiling<T>(string address) where T : Object
   809→    {
   810→        var record = new LoadRecord
   811→        {
   812→            Address = address,
   813→            StartTime = Time.realtimeSinceStartup
   814→        };
   815→
   816→        var handle = Addressables.LoadAssetAsync<T>(address);
   817→        await handle.Task;
   818→
   819→        record.Duration = Time.realtimeSinceStartup - record.StartTime;
   820→        record.Success = handle.Status == AsyncOperationStatus.Succeeded;
   821→
   822→        loadRecords.Add(record);
   823→        if (loadRecords.Count > maxRecords)
   824→        {
   825→            loadRecords.RemoveAt(0);
   826→        }
   827→
   828→        if (record.Duration > 0.5f) // 超过500ms警告
   829→        {
   830→            Debug.LogWarning($"Slow load: {address} took {record.Duration * 1000:F0}ms");
   831→        }
   832→
   833→        return record.Success ? handle.Result : null;
   834→    }
   835→
   836→    /// <summary>
   837→    /// 获取性能报告
   838→    /// </summary>
   839→    public string GetPerformanceReport()
   840→    {
   841→        if (loadRecords.Count == 0)
   842→            return "No load records";
   843→
   844→        var sb = new System.Text.StringBuilder();
   845→        sb.AppendLine("=== Addressables Performance Report ===");
   846→
   847→        float avgDuration = loadRecords.Average(r => r.Duration);
   848→        float maxDuration = loadRecords.Max(r => r.Duration);
   849→        int slowLoads = loadRecords.Count(r => r.Duration > 0.5f);
   850→
   851→        sb.AppendLine($"Total loads: {loadRecords.Count}");
   852→        sb.AppendLine($"Average duration: {avgDuration * 1000:F1}ms");
   853→        sb.AppendLine($"Max duration: {maxDuration * 1000:F1}ms");
   854→        sb.AppendLine($"Slow loads (>500ms): {slowLoads}");
   855→
   856→        return sb.ToString();
   857→    }
   858→}
   859→```
