    68→## 二、异步加载实现
    69→
    70→### 2.1 基础异步加载
    71→
    72→```csharp
    73→using System.Collections;
    74→using UnityEngine;
    75→
    76→/// <summary>
    77→/// 资源加载器 - 基础版
    78→/// </summary>
    79→public class ResourceLoader : MonoBehaviour
    80→{
    81→    /// <summary>
    82→    /// 异步加载单个资源
    83→    /// </summary>
    84→    public IEnumerator LoadAssetAsync<T>(string path, System.Action<T> onComplete) where T : Object
    85→    {
    86→        var loadOperation = Resources.LoadAsync<T>(path);
    87→
    88→        while (!loadOperation.isDone)
    89→        {
    90→            // 可在这里更新进度条
    91→            Debug.Log($"加载进度: {loadOperation.progress * 100}%");
    92→            yield return null;
    93→        }
    94→
    95→        if (loadOperation.asset != null)
    96→        {
    97→            onComplete?.Invoke(loadOperation.asset as T);
    98→        }
    99→        else
   100→        {
   101→            Debug.LogError($"加载失败: {path}");
   102→        }
   103→    }
   104→
   105→    /// <summary>
   106→    /// 异步加载多个资源
   107→    /// </summary>
   108→    public IEnumerator LoadAssetsAsync<T>(string[] paths, System.Action<T[]> onComplete) where T : Object
   109→    {
   110→        var assets = new T[paths.Length];
   111→        var loadOperations = new ResourceRequest[paths.Length];
   112→
   113→        // 同时开始所有加载
   114→        for (int i = 0; i < paths.Length; i++)
   115→        {
   116→            loadOperations[i] = Resources.LoadAsync<T>(paths[i]);
   117→        }
   118→
   119→        // 等待所有加载完成
   120→        bool allDone = false;
   121→        while (!allDone)
   122→        {
   123→            allDone = true;
   124→            float totalProgress = 0f;
   125→
   126→            for (int i = 0; i < loadOperations.Length; i++)
   127→            {
   128→                if (!loadOperations[i].isDone)
   129→                {
   130→                    allDone = false;
   131→                }
   132→                totalProgress += loadOperations[i].progress;
   133→            }
   134→
   135→            float avgProgress = totalProgress / loadOperations.Length;
   136→            Debug.Log($"总加载进度: {avgProgress * 100}%");
   137→
   138→            yield return null;
   139→        }
   140→
   141→        // 收集结果
   142→        for (int i = 0; i < paths.Length; i++)
   143→        {
   144→            assets[i] = loadOperations[i].asset as T;
   145→        }
   146→
   147→        onComplete?.Invoke(assets);
   148→    }
   149→}
   150→```
