   222→### 3.2 分阶段加载实现
   223→
   224→```csharp
   225→using System;
   226→using System.Collections;
   227→using System.Collections.Generic;
   228→using UnityEngine;
   229→
   230→/// <summary>
   231→/// 资源优先级
   232→/// </summary>
   233→public enum AssetPriority
   234→{
   235→    P0_Immediate,  // 立即加载
   236→    P1_High,       // 优先加载
   237→    P2_Normal,     // 延迟加载
   238→    P3_Low         // 按需加载
   239→}
   240→
   241→/// <summary>
   242→/// 分阶段资源加载器
   243→/// </summary>
   244→public class PhasedAssetLoader : MonoBehaviour
   245→{
   246→    [System.Serializable]
   247→    public class AssetGroup
   248→    {
   249→        public AssetPriority priority;
   250→        public string[] paths;
   251→    }
   252→
   253→    [Header("资源配置")]
   254→    [SerializeField] private AssetGroup[] assetGroups;
   255→
   256→    public event Action<float> OnProgressChanged;
   257→    public event Action OnLoadComplete;
   258→
   259→    /// <summary>
   260→    /// 分阶段加载
   261→    /// </summary>
   262→    public IEnumerator LoadAllPhased()
   263→    {
   264→        float totalProgress = 0f;
   265→        float groupWeight = 1f / assetGroups.Length;
   266→
   267→        foreach (var group in assetGroups)
   268→        {
   269→            yield return StartCoroutine(LoadGroup(group, progress =>
   270→            {
   271→                float weightedProgress = progress * groupWeight;
   272→                OnProgressChanged?.Invoke(totalProgress + weightedProgress);
   273→            }));
   274→
   275→            totalProgress += groupWeight;
   276→        }
   277→
   278→        OnLoadComplete?.Invoke();
   279→    }
   280→
   281→    private IEnumerator LoadGroup(AssetGroup group, Action<float> onProgress)
   282→    {
   283→        int total = group.paths.Length;
   284→        int loaded = 0;
   285→
   286→        foreach (string path in group.paths)
   287→        {
   288→            var loadOp = Resources.LoadAsync<GameObject>(path);
   289→
   290→            while (!loadOp.isDone)
   291→            {
   292→                float groupProgress = (float)loaded / total + loadOp.progress / total;
   293→                onProgress?.Invoke(groupProgress);
   294→                yield return null;
   295→            }
   296→
   297→            loaded++;
   298→            onProgress?.Invoke((float)loaded / total);
   299→        }
   300→    }
   301→}
   302→```
