   342→## 四、进度反馈实现
   343→
   344→### 4.1 优雅的加载界面
   345→
   346→```csharp
   347→using UnityEngine;
   348→using UnityEngine.UI;
   349→
   350→public class LoadingScreen : MonoBehaviour
   351→{
   352→    [Header("UI元素")]
   353→    [SerializeField] private Slider progressBar;
   354→    [SerializeField] private Text progressText;
   355→    [SerializeField] private Text tipText;
   356→    [SerializeField] private Image backgroundImage;
   357→
   358→    [Header("提示文本")]
   359→    [SerializeField] private string[] tips;
   360→
   361→    [Header("动画")]
   362→    [SerializeField] private float barSmoothSpeed = 5f;
   363→
   364→    private float displayedProgress;
   365→    private float targetProgress;
   366→
   367→    private void OnEnable()
   368→    {
   369→        // 随机显示提示
   370→        if (tips != null && tips.Length > 0)
   371→        {
   372→            tipText.text = tips[UnityEngine.Random.Range(0, tips.Length)];
   373→        }
   374→    }
   375→
   376→    private void Update()
   377→    {
   378→        // 平滑进度条
   379→        displayedProgress = Mathf.Lerp(displayedProgress, targetProgress, Time.deltaTime * barSmoothSpeed);
   380→
   381→        if (progressBar != null)
   382→        {
   383→            progressBar.value = displayedProgress;
   384→        }
   385→
   386→        if (progressText != null)
   387→        {
   388→            progressText.text = $"{(int)(displayedProgress * 100)}%";
   389→        }
   390→    }
   391→
   392→    /// <summary>
   393→    /// 更新进度
   394→    /// </summary>
   395→    public void UpdateProgress(float progress)
   396→    {
   397→        targetProgress = Mathf.Clamp01(progress);
   398→    }
   399→
   400→    /// <summary>
   401→    /// 隐藏加载界面
   402→    /// </summary>
   403→    public void Hide()
   404→    {
   405→        // 播放淡出动画
   406→        gameObject.SetActive(false);
   407→    }
   408→}
