   442→
   443→## 五、后台预加载
   444→
   445→### 5.1 场景闲置时预加载
   446→
   447→```csharp
   448→/// <summary>
   449→/// 后台预加载管理器
   450→/// </summary>
   451→public class BackgroundPreloader : MonoBehaviour
   452→{
   453→    private Queue<string> preloadQueue = new Queue<string>();
   454→    private bool isPreloading = false;
   455→
   456→    /// <summary>
   457→    /// 添加预加载任务
   458→    /// </summary>
   459→    public void AddPreloadTask(string path)
   460→    {
   461→        preloadQueue.Enqueue(path);
   462→    }
   463→
   464→    /// <summary>
   465→    /// 在合适时机执行预加载
   466→    /// </summary>
   467→    public void TryStartPreload()
   468→    {
   469→        if (!isPreloading && preloadQueue.Count > 0)
   470→        {
   471→            StartCoroutine(PreloadNext());
   472→        }
   473→    }
   474→
   475→    private IEnumerator PreloadNext()
   476→    {
   477→        isPreloading = true;
   478→
   479→        while (preloadQueue.Count > 0)
   480→        {
   481→            string path = preloadQueue.Dequeue();
   482→            var loadOp = Resources.LoadAsync<GameObject>(path);
   483→
   484→            while (!loadOp.isDone)
   485→            {
   486→                // 如果游戏进入忙碌状态，暂停预加载
   487→                if (IsGameBusy())
   488→                {
   489→                    yield return new WaitUntil(() => !IsGameBusy());
   490→                }
   491→
   492→                yield return null;
   493→            }
   494→        }
   495→
   496→        isPreloading = false;
   497→    }
   498→
   499→    private bool IsGameBusy()
   500→    {
   501→        // 判断游戏是否忙碌（例如：战斗中、动画播放中）
   502→        return false;  // 根据实际情况实现
   503→    }
   504→}
   505→```
