   545→## 六、Addressables加载
   546→
   547→### 6.1 为什么使用Addressables
   548→
   549→```
   550→传统Resources加载的问题：
   551→├─ 所有资源打包进游戏
   552→├─ 无法热更新
   553→├─ 内存占用高
   554→└─ 加载时间长
   555→
   556→Addressables的优势：
   557→├─ 资源可远程下载
   558→├─ 支持热更新
   559→├─ 内存管理更灵活
   560→├─ 异步加载
   561→└─ 支持依赖管理
   562→```
   563→
   564→---
   565→
   566→### 6.2 Addressables基础使用
   567→
   568→```csharp
   569→using System.Collections;
   570→using UnityEngine;
   571→using UnityEngine.Addressables;
   572→using UnityEngine.ResourceManagement.AsyncOperations;
   573→
   574→public class AddressablesLoader : MonoBehaviour
   575→{
   576→    /// <summary>
   577→    /// 加载单个资源
   578→    /// </summary>
   579→    public IEnumerator LoadAssetAsync(string address, System.Action<GameObject> onComplete)
   580→    {
   581→        AsyncOperationHandle<GameObject> handle = Addressables.LoadAssetAsync<GameObject>(address);
   582→
   583→        while (!handle.IsDone)
   584→        {
   585→            Debug.Log($"加载进度: {handle.PercentComplete * 100}%");
   586→            yield return null;
   587→        }
   588→
   589→        if (handle.Status == AsyncOperationStatus.Succeeded)
   590→        {
   591→            onComplete?.Invoke(handle.Result);
   592→        }
   593→        else
   594→        {
   595→            Debug.LogError($"加载失败: {address}");
   596→        }
   597→
   598→        // 使用完后释放
   599→        // Addressables.Release(handle);
   600→    }
   601→
   602→    /// <summary>
   603→    /// 加载场景
   604→    /// </summary>
   605→    public IEnumerator LoadSceneAsync(string address)
   606→    {
   607→        var handle = Addressables.LoadSceneAsync(address);
   608→
   609→        while (!handle.IsDone)
   610→        {
   611→            Debug.Log($"场景加载进度: {handle.PercentComplete * 100}%");
   612→            yield return null;
   613→        }
   614→    }
   615→}
   616→```
