   153→## 3. 解决方案
   154→
   155→### 3.1 迁移到 Addressables
   156→
   157→**问题**：Resources.Load 同步加载阻塞主线程
   158→
   159→**方案**：使用 Addressables 异步加载
   160→
   161→#### 步骤1：资源迁移
   162→
   163→```csharp
   164→/// <summary>
   165→/// 资源加载服务 - Addressables封装
   166→/// </summary>
   167→public class AssetLoader : MonoBehaviour
   168→{
   169→    private Dictionary<string, AsyncOperationHandle> loadedHandles = new Dictionary<string, AsyncOperationHandle>();
   170→
   171→    /// <summary>
   172→    /// 异步加载单个资源
   173→    /// </summary>
   174→    public async Task<T> LoadAssetAsync<T>(string address) where T : Object
   175→    {
   176→        // 检查缓存
   177→        if (loadedHandles.TryGetValue(address, out var existingHandle))
   178→        {
   179→            if (existingHandle.IsDone)
   180→            {
   181→                return existingHandle.Result as T;
   182→            }
   183→            await existingHandle.Task;
   184→            return existingHandle.Result as T;
   185→        }
   186→
   187→        // 异步加载
   188→        var handle = Addressables.LoadAssetAsync<T>(address);
   189→        loadedHandles[address] = handle;
   190→
   191→        await handle.Task;
   192→
   193→        if (handle.Status == AsyncOperationStatus.Succeeded)
   194→        {
   195→            return handle.Result;
   196→        }
   197→
   198→        Debug.LogError($"Failed to load asset: {address}");
   199→        return null;
   200→    }
   201→
   202→    /// <summary>
   203→    /// 批量异步加载
   204→    /// </summary>
   205→    public async Task<List<T>> LoadAssetsAsync<T>(IList<string> addresses) where T : Object
   206→    {
   207→        var results = new List<T>();
   208→        var tasks = new List<Task<T>>();
   209→
   210→        foreach (var address in addresses)
   211→        {
   212→            tasks.Add(LoadAssetAsync<T>(address));
   213→        }
   214→
   215→        var loadedAssets = await Task.WhenAll(tasks);
   216→        results.AddRange(loadedAssets.Where(a => a != null));
   217→
   218→        return results;
   219→    }
   220→
   221→    /// <summary>
   222→    /// 释放资源
   223→    /// </summary>
   224→    public void ReleaseAsset(string address)
   225→    {
   226→        if (loadedHandles.TryGetValue(address, out var handle))
   227→        {
   228→            Addressables.Release(handle);
   229→            loadedHandles.Remove(address);
   230→        }
   231→    }
   232→
   233→    /// <summary>
   234→    /// 释放所有资源
   235→    /// </summary>
   236→    public void ReleaseAll()
   237→    {
   238→        foreach (var handle in loadedHandles.Values)
   239→        {
   240→            Addressables.Release(handle);
   241→        }
   242→        loadedHandles.Clear();
   243→    }
   244→}
   245→```
   246→
   247→#### 步骤2：重构UI资源加载
   248→
   249→```csharp
   250→/// <summary>
   251→/// UI管理器 - 异步加载版本
   252→/// </summary>
   253→public class UIManager : MonoBehaviour
   254→{
   255→    [SerializeField] private AssetLoader assetLoader;
   256→
   257→    private Dictionary<string, GameObject> cachedPanels = new Dictionary<string, GameObject>();
   258→
   259→    /// <summary>
   260→    /// 异步打开面板
   261→    /// </summary>
   262→    public async Task<T> OpenPanelAsync<T>(string panelAddress) where T : Component
   263→    {
   264→        // 检查缓存
   265→        if (cachedPanels.TryGetValue(panelAddress, out var cachedPanel))
   266→        {
   267→            cachedPanel.SetActive(true);
   268→            return cachedPanel.GetComponent<T>();
   269→        }
   270→
   271→        // 异步加载
   272→        var prefab = await assetLoader.LoadAssetAsync<GameObject>(panelAddress);
   273→        if (prefab == null) return null;
   274→
   275→        // 实例化
   276→        var panel = Instantiate(prefab, transform);
   277→        cachedPanels[panelAddress] = panel;
   278→
   279→        return panel.GetComponent<T>();
   280→    }
   281→
   282→    /// <summary>
   283→    /// 关闭面板（回收到缓存）
   284→    /// </summary>
   285→    public void ClosePanel(string panelAddress)
   286→    {
   287→        if (cachedPanels.TryGetValue(panelAddress, out var panel))
   288→        {
   289→            panel.SetActive(false);
   290→        }
   291→    }
   292→}
   293→```
