   561→### 3.5 智能预加载策略
   562→
   563→**问题**：全部资源一次性加载太慢
   564→
   565→**方案**：按优先级分层预加载
   566→
   567→```csharp
   568→/// <summary>
   569→/// 智能预加载管理器
   570→/// </summary>
   571→public class SmartPreloader : MonoBehaviour
   572→{
   573→    [System.Serializable]
   574→    public class PreloadGroup
   575→    {
   576→        public string groupName;
   577→        public List<string> assetAddresses;
   578→        public PreloadPriority priority;
   579→        public bool showInLoading;
   580→    }
   581→
   582→    public enum PreloadPriority
   583→    {
   584→        Critical,   // 启动必须，立即加载
   585→        High,       // 首屏需要，启动后加载
   586→        Normal,     // 游戏中需要，后台加载
   587→        Low         // 可选内容，空闲加载
   588→    }
   589→
   590→    [Header("Preload Groups")]
   591→    [SerializeField] private List<PreloadGroup> preloadGroups;
   592→
   593→    private Dictionary<string, float> loadProgress = new Dictionary<string, float>();
   594→
   595→    /// <summary>
   596→    /// 开始预加载
   597→    /// </summary>
   598→    public async Task StartPreload(Action<float> onProgress)
   599→    {
   600→        // 按优先级分组
   601→        var criticalGroup = preloadGroups.Where(g => g.priority == PreloadPriority.Critical);
   602→        var highGroup = preloadGroups.Where(g => g.priority == PreloadPriority.High);
   603→        var normalGroup = preloadGroups.Where(g => g.priority == PreloadPriority.Normal);
   604→        var lowGroup = preloadGroups.Where(g => g.priority == PreloadPriority.Low);
   605→
   606→        int totalGroups = preloadGroups.Count;
   607→        int completedGroups = 0;
   608→
   609→        // 1. 加载关键资源（阻塞）
   610→        foreach (var group in criticalGroup)
   611→        {
   612→            await LoadGroup(group);
   613→            completedGroups++;
   614→            onProgress?.Invoke((float)completedGroups / totalGroups);
   615→        }
   616→
   617→        // 2. 启动游戏（关键资源加载完成即可）
   618→        // ... 允许玩家进入游戏 ...
   619→
   620→        // 3. 后台加载高优先级资源
   621→        _ = Task.Run(async () =>
   622→        {
   623→            foreach (var group in highGroup)
   624→            {
   625→                await LoadGroup(group);
   626→                completedGroups++;
   627→                MainThreadDispatcher.ExecuteOnMainThread(() =>
   628→                    onProgress?.Invoke((float)completedGroups / totalGroups));
   629→            }
   630→
   631→            // 4. 空闲时加载普通资源
   632→            foreach (var group in normalGroup)
   633→            {
   634→                await LoadGroup(group);
   635→                completedGroups++;
   636→            }
   637→
   638→            // 5. 低优先级资源
   639→            foreach (var group in lowGroup)
   640→            {
   641→                await LoadGroup(group);
   642→                completedGroups++;
   643→            }
   644→        });
   645→    }
   646→
   647→    private async Task LoadGroup(PreloadGroup group)
   648→    {
   649→        var tasks = group.assetAddresses.Select(addr =>
   650→            Addressables.LoadAssetAsync<Object>(addr).Task);
   651→
   652→        await Task.WhenAll(tasks);
   653→    }
   654→}
   655→```
